INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT149-S4-Q1$batch04$, 149, 4, 1, $batch04$Paradox$batch04$, $batch04$Dentist: I recommend brushing one’s teeth after every meal to remove sugars that facilitate the growth of certain bacteria; these bacteria produce acid that dissolves minerals in tooth enamel, resulting in cavities. And when brushing is not practical, I recommend chewing gum—even gum that contains sugar—to prevent the formation of cavities.$batch04$, $batch04$Which one of the following, if true, would most help to reconcile the dentist’s apparently paradoxical recommendations?$batch04$, $batch04$C$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=149 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT149-S4-Q1$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$A piece of chewing gum that contains sugar contains far less sugar than does the average meal.$batch04$, $batch04$Too Weak$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Tooth decay can be stopped and reversed if it is caught before a cavity develops.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$Chewing gum stimulates the production of saliva, which reduces acidity in the mouth and helps remineralize tooth enamel.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Sugars can be on teeth for as long as 24 hours before the teeth-damaging bacteria whose growth they facilitate begin to proliferate.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Chewing gum exercises and relaxes the jaw muscles and so contributes to the overall health of the oral tract.$batch04$, $batch04$Out of Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$The dentist says to brush after meals to remove sugars, because those sugars feed bacteria whose acid causes cavities.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$The dentist recommends chewing gum, even gum with sugar, to prevent cavities?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Sugary gum adds sugar, which the dentist says is bad. So chewing must help in some other way that outweighs the sugar, ideally by fighting the acid or repairing the enamel.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a cavity-fighting benefit of chewing gum.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Gum has less sugar than a meal, but it still adds sugar. This makes the gum less harmful, not helpful.$batch04$), ($batch04$B$batch04$, $batch04$Decay being reversible if caught early does not explain why gum helps.$batch04$), ($batch04$C$batch04$, $batch04$Chewing gum makes saliva, which reduces acid and helps rebuild enamel. That benefit outweighs the small amount of sugar.$batch04$), ($batch04$D$batch04$, $batch04$If sugar takes 24 hours to cause harm, brushing after every meal seems less urgent. That does not explain why gum would help.$batch04$), ($batch04$E$batch04$, $batch04$Healthy jaw muscles are not cavities.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT149-S4-Q1$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
